import { exists, files, readText, within } from './files.js';

export interface ActiveChangeContext {
  changeId: string;
  generation: number;
  requirementIds: string[];
}

interface StoredChangeGeneration {
  changeId: string;
  generation?: number;
  activeGeneration?: number | null;
  requirementIds?: string[];
}

function activeGeneration(change: StoredChangeGeneration): number | null {
  if (change.activeGeneration === null) return null;
  return change.activeGeneration ?? change.generation ?? 1;
}

function changeDocumentStatus(source: string): 'active' | 'completed' {
  const frontmatter = /^---\r?\n([\s\S]*?)\r?\n---(?:\r?\n|$)/.exec(source)?.[1];
  const status = frontmatter === undefined
    ? null
    : /^status:\s*(active|completed)\s*$/m.exec(frontmatter)?.[1];
  return status === 'completed' ? 'completed' : 'active';
}

async function implicitlyActiveChangeIds(root: string): Promise<Set<string>> {
  const ids = new Set<string>();
  for (const path of (await files(root)).filter((candidate) =>
    /^\.musubix\/changes\/CHANGE-\d+\.md$/.test(candidate))) {
    if (changeDocumentStatus(await readText(root, path)) === 'active') {
      ids.add(path.slice('.musubix/changes/'.length, -'.md'.length));
    }
  }
  return ids;
}

/** @id CODE-M5-GENERATION-CONTEXT-001
 * @implements REQ-M5-LIFECYCLE-005 REQ-M5-APPROVAL-007 REQ-M5-TDD-003
 * @design DES-M5-005 DES-M5-006 DES-M5-011
 */
export async function activeChangeContext(root: string): Promise<ActiveChangeContext | null> {
  const path = '.musubix/evidence/changes.json';
  if (!await exists(within(root, path))) return null;
  const evidence = JSON.parse(await readText(root, path)) as {
    schemaVersion?: unknown;
    changes?: StoredChangeGeneration[];
  };
  if (evidence.schemaVersion !== 1 || !Array.isArray(evidence.changes)) {
    throw new Error('Invalid change chronology evidence.');
  }
  const selectableChangeIds = await implicitlyActiveChangeIds(root);
  const active = evidence.changes.flatMap((change) => {
    if (!selectableChangeIds.has(change.changeId)) return [];
    const generation = activeGeneration(change);
    return generation === null ? [] : [{
      changeId: change.changeId,
      generation,
      requirementIds: Array.isArray(change.requirementIds) ? change.requirementIds : [],
    }];
  });
  if (active.length > 1) {
    throw new Error('CHANGE_GENERATION_MIXED: more than one CHANGE has an active generation.');
  }
  return active[0] ?? null;
}

import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, describe, expect, it } from 'vitest';
import { activeChangeContext } from '../packages/analysis/src/change-generation.js';

const temporaryDirectories: string[] = [];

function write(root: string, path: string, content: string): void {
  const destination = join(root, path);
  mkdirSync(join(destination, '..'), { recursive: true });
  writeFileSync(destination, content);
}

afterEach(() => {
  for (const directory of temporaryDirectories.splice(0)) {
    rmSync(directory, { recursive: true, force: true });
  }
});

describe('active CHANGE context', () => {
  /** @id TEST-M5-LIFECYCLE-ACTIVE-STATUS-001
   * @verifies REQ-M5-LIFECYCLE-005
   */
  it('TEST-M5-LIFECYCLE-ACTIVE-STATUS-001 excludes completed CHANGE documents from implicit selection', async () => {
    const root = mkdtempSync(join(tmpdir(), 'musubix5-active-change-'));
    temporaryDirectories.push(root);
    write(root, '.musubix/changes/CHANGE-0002.md', [
      '---',
      'schemaVersion: 1',
      'id: CHANGE-0002',
      'status: completed',
      '---',
      '# CHANGE-0002',
      '',
    ].join('\n'));
    write(root, '.musubix/changes/CHANGE-0003.md', [
      '---',
      'schemaVersion: 1',
      'id: CHANGE-0003',
      'status: active',
      '---',
      '# CHANGE-0003',
      '',
    ].join('\n'));
    write(root, '.musubix/evidence/changes.json', JSON.stringify({
      schemaVersion: 1,
      changes: [
        { changeId: 'CHANGE-0002', activeGeneration: 15, requirementIds: ['REQ-OLD-001'] },
        { changeId: 'CHANGE-0003', activeGeneration: 5, requirementIds: ['REQ-NEW-001'] },
      ],
    }));

    await expect(activeChangeContext(root)).resolves.toEqual({
      changeId: 'CHANGE-0003',
      generation: 5,
      requirementIds: ['REQ-NEW-001'],
    });
  });
});
